import { ActionDefinition } from '../../../Action'
import {
    BooleanColumn,
    StringColumn,
    TableNameColumn,
    ReferenceColumn,
    DocumentIdColumn,
    TemplateValueColumn,
    SlushBucketColumn,
} from '../../../../db'

export const createCatalogTask = ActionDefinition({
    $id: 'af51fd0e73141300612c273ffff6a785',
    name: 'Create Catalog Task',
    description: `<p>Creates a Catalog Task on a Service Catalog Request Item [sc_req_item]. The task can be configured to be
      a blocking or non-blocking task.</p>
      <p>Pass Catalog Variables to the task to provide additional information or to allow the fulfiller to modify the
      variables. To pass variables from the Catalog Request Item, configure a template catalog item to populate the
      available catalog variables and select which ones will be applied to the task.  Any changes to variables during
      task fulfillment will be updated on the Catalog Request Item.</p>
      <p>To associate variables to the task that are associated with the flow configure your Flow Service Catalog
      variables <a href="https://docs.servicenow.com/?context=CSHelp:Flow-Designer-Catalog-Task" target="_blank">learn more</a>. These variables are named "Flow:variablename".  When a Flow variable is associated to a
      Catalog Task, it will be applied to the corresponding Catalog Request Item.</p>`,
    category: 'bf2f2fec73f70300b61e66476bf6a774',
    inputs: {
        ah_wait: BooleanColumn({
            label: 'Wait',
            default: true,
        }),
        ah_fields: TemplateValueColumn({
            label: 'Fields',
            maxLength: 65000,
            dependent: 'ah_table_name',
        }),
        catalog_variables: SlushBucketColumn({
            label: 'Catalog Variables',
            maxLength: 12000,
        }),
        ah_short_description: StringColumn({
            label: 'Short Description',
            maxLength: 12000,
        }),
        ah_table_name: TableNameColumn({
            label: 'Table Name',
            default: 'sc_task',
            readOnly: true,
        }),
        template_catalog_item: ReferenceColumn({
            label: 'Template Catalog Item',
            referenceTable: 'sc_cat_item',
        }),
        ah_requested_item: ReferenceColumn({
            label: 'Requested Item',
            mandatory: true,
            referenceTable: 'sc_req_item',
        }),
    },
    outputs: {
        'Catalog Task': DocumentIdColumn({
            label: 'Catalog Task',
            dependent: 'ah_table_name',
        }),
    },
})
